<script setup>import{ref,onMounted}from'vue';import api from'../services/api.js';import PageHero from'../components/PageHero.vue';const topics=ref([]);onMounted(async()=>topics.value=await api.get('/public/topics'))</script>
<template><PageHero image="/uploads/demo/banners/banner-008.png" eyebrow="TRAVEL COLLECTIONS" title="用一个主题，打开旅行灵感" subtitle="毕业旅行、古城慢游、周末短途或为了一顿饭出发。选择此刻最想过的生活。"/><div class="container topics-page"><router-link v-for="(topic,index) in topics" :key="topic.id" :to="`/topic/${topic.id}`" class="topic"><img :src="topic.coverImage"><div class="topic-no">{{String(index+1).padStart(2,'0')}}</div><div class="topic-copy"><span>CURATED COLLECTION</span><h2>{{topic.name}}</h2><p>{{topic.subtitle}}</p><small>{{topic.summary}}</small></div></router-link></div></template>
<style scoped>.topics-page{padding:50px 0 90px;display:grid;grid-template-columns:repeat(2,1fr);gap:25px}.topic{height:390px;position:relative;overflow:hidden;border-radius:20px;color:white}.topic img{width:100%;height:100%;object-fit:cover;transition:.5s}.topic:hover img{transform:scale(1.04)}.topic:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(6,36,42,.9),rgba(6,36,42,.02) 75%)}.topic-no{position:absolute;z-index:2;right:24px;top:18px;font:42px Georgia;color:rgba(255,255,255,.55)}.topic-copy{position:absolute;z-index:2;left:28px;right:28px;bottom:28px}.topic-copy>span{font-size:9px;letter-spacing:3px;color:#b7e9ea}.topic h2{font:30px Georgia,"Songti SC",serif;margin:8px 0}.topic p{margin:0 0 8px}.topic small{color:rgba(255,255,255,.7)}@media(max-width:680px){.topics-page{grid-template-columns:1fr}.topic{height:330px}}</style>

